-- ----------------------------
-- Function structure for uuid_v7
-- ----------------------------
DROP FUNCTION IF EXISTS "domain_core"."uuid_v7"();
CREATE FUNCTION "domain_core"."uuid_v7"()
  RETURNS "pg_catalog"."uuid" AS $BODY$
SELECT
  upper(
    (
      lpad(to_hex((extract(epoch from clock_timestamp()) * 1000)::bigint), 12, '0') ||
      lpad(to_hex((random() * 2^12)::int), 3, '0') ||
      '7' ||
      lpad(to_hex((random() * 2^62)::bigint), 16, '0')
    )::text
  )::uuid;
$BODY$
  LANGUAGE sql VOLATILE
  COST 100;

